package com.vibeguard.samples.apikeys; import jakarta.validation.Valid; import jakarta.validation.constraints.NotBlank; import java.nio.charset.StandardCharsets; import java.security.*; import java.util.*; import java.util.concurrent.ConcurrentHashMap; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*; /** Mints opaque integration credentials and stores only their hashes. */ @RestController @RequestMapping("/internal/api-keys") public class ApiKeyController { private final Map<String,String> hashes=new ConcurrentHashMap<>(); private final SecureRandom random=new SecureRandom(); @Value("${API_KEY_ADMIN_KEY:}") private String adminKey; @PostMapping public ResponseEntity<Issued> issue(@RequestHeader("X-Api-Key-Admin-Key") String supplied,@Valid @RequestBody Request request)throws Exception{if(!adminKey.equals(supplied))return ResponseEntity.status(401).build();byte[] bytes=new byte[32];random.nextBytes(bytes);String raw=Base64.getUrlEncoder().withoutPadding().encodeToString(bytes);String id=UUID.randomUUID().toString();hashes.put(id,hash(raw));return ResponseEntity.status(201).body(new Issued(id,raw,request.integration()));}@DeleteMapping("/{id}") public ResponseEntity<Void> revoke(@RequestHeader("X-Api-Key-Admin-Key") String supplied,@PathVariable String id){if(!adminKey.equals(supplied))return ResponseEntity.status(401).build();hashes.remove(id);return ResponseEntity.noContent().build();}private String hash(String raw)throws Exception{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(raw.getBytes(StandardCharsets.UTF_8)));}record Request(@NotBlank String integration){}record Issued(String id,String apiKey,String integration){} }
